"""Source-reviewed Banner November PA guides. Never modify formulary coverage flags."""
import copy,hashlib,json,sqlite3,re,shutil
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
PDF='/sources/prov-bufc_pharmacy-pa-criteria_eff11012026_en.pdf'
GUIDES=[]
META={713:('GLP-1 Agonists - AZM','GL-715192',718),1567:('SGLT-2 Inhibitors - AZM','GL-589207',1573),365:('Combination Basal Insulin/GLP-1 Receptor Agonist','GL-398215',367),265:('Breztri, Trelegy Ellipta - AZM','GL-642189',267),961:('Inhaled Corticosteroids - AZM','GL-589212',962),969:('Insulins, Concentrated- Arizona','GL-154074',970)}
MET='Failure of metformin ≥1,500 mg/day for 90 days, or contraindication/intolerance to metformin.'
DPP='Attest no concurrent DPP-4 inhibitor-containing agent, OR document a plan to address concomitant use.'
GLP_BASE=['Chart notes confirm type 2 diabetes and baseline A1c ≥6.5%.','Chart notes or paid claims document: '+MET,DPP]
PREF_GLP='Chart notes or paid claims document a 90-day trial resulting in therapeutic failure, contraindication or intolerance to ALL: Trulicity; brand Victoza or generic liraglutide; and Mounjaro.'
NO_RENEW='Separate renewal criteria are not stated in this section; do not infer an automatic renewal rule.'
def add(key,title,section,pages,products,indication,requirements,branches=None,renewal=None,stage='Approval criteria; therapy stage not specified',notes=None,ambiguity=None):
 name,code,end=META[section]
 g=dict(id='banner-guide-'+key,recordType='policy',planId='banner-ufc',name=title,brand='',category='Respiratory / Allergy' if section in [265,961] else 'Diabetes',subcategory='Banner PA approval guides',coverage='policy_only',preferred='not_specified',pa='not_specified',paText='',step='not_specified',stepText='',qlAmount='',qlDays='',conditions=[],indication=indication,stage=stage,approvalDuration='12 months',sourceTitle=name,sourceEffective='2026-11-01',sourcePage=min(pages),sourceLastPage=max(pages),sourcePages=pages,sourceUrl=PDF,sourceTextUrl=f'/banner-policy-text/12-{section}.txt',validation='source_reviewed_summary_not_clinician_approved',policyCode=code,guide=dict(products=products,requirements=requirements,branches=branches or [],renewal=renewal,renewalStatus='stated' if renewal else 'not_stated',notes=notes or [],ambiguity=ambiguity,scope='Use when a PA is requested for this product and indication. A policy guide does not establish formulary coverage or that PA is always required.',sourceSectionFirstPage=section,sourceSectionLastPage=end))
 GUIDES.append(g);return g
add('glp-preferred','Mounjaro / Trulicity / Victoza / generic liraglutide',713,[713,714],['Mounjaro','Trulicity','Victoza','generic liraglutide'],'Type 2 diabetes',GLP_BASE+['Age ≥10 years.'],notes=['Policy scope excludes weight loss/appetite suppression and obesity-related uses, including Zepbound for OSA; other indications are denied under this section.','This PA policy calls these products preferred; the formulary’s separate preferred-status field remains unchanged.'])
add('glp-nonpreferred-injection','Ozempic injection / exenatide',713,[714,715],['Ozempic injection','exenatide'],'Type 2 diabetes',GLP_BASE+[PREF_GLP,'Age ≥18 years.'],notes=['Weight loss/appetite suppression and obesity-related uses are excluded; other indications are denied under this section.'])
add('glp-oral','Rybelsus / Ozempic tablets',713,[715,716,717],['Rybelsus','Ozempic tablets'],'Type 2 diabetes',GLP_BASE+['Age ≥18 years.'],branches=[dict(label='ONE of these pathways is required',options=[PREF_GLP,'BOTH: documented inability to self-inject due to physical impairment, visual impairment, lipohypertrophy, or documented needle phobia causing prior refusal of injectable therapy/medical procedures; AND chart notes/paid claims document a 90-day trial resulting in therapeutic failure, contraindication or intolerance to ALL: Farxiga, Jardiance, Synjardy and Xigduo XR.'])],notes=['Weight loss/appetite suppression and obesity-related uses are excluded; other indications are denied under this section.'])
add('farxiga','Farxiga / generic dapagliflozin',1567,[1567,1568],['Farxiga','generic dapagliflozin'],'Type 2 diabetes OR CKD OR qualifying heart failure',[],branches=[dict(label='ONE indication pathway',options=['Type 2 diabetes: age ≥10 years AND '+MET,'CKD; OR heart failure NYHA II–IV with reduced EF; OR heart failure NYHA II–IV with preserved EF.'])],notes=['Generic dapagliflozin requests ALSO require failure, intolerance or contraindication to brand Farxiga.','The CKD/HF branch does not state a metformin trial or separate age threshold; do not carry diabetes-only requirements into it.'])
add('jardiance','Jardiance',1567,[1568,1569],['Jardiance'],'Type 2 diabetes OR qualifying cardiovascular, HF or CKD indication',[],branches=[dict(label='ONE indication pathway',options=['Type 2 diabetes: age ≥10 years AND '+MET,'CV death risk reduction: adult with type 2 diabetes and established cardiovascular disease AND '+MET,'Adult with heart failure: reduce CV death and HF hospitalization; OR adult with CKD at risk of progression: reduce sustained eGFR decline, ESKD, CV death and hospitalization.'])],notes=['The HF/CKD pathway does not state a metformin trial.'])
add('synjardy','Synjardy / Synjardy XR',1567,[1569],['Synjardy','Synjardy XR'],'Type 2 diabetes',['Age ≥10 years.','Type 2 diabetes diagnosis.',MET],notes=['Synjardy XR ONLY: also document failure, intolerance or contraindication to BOTH brand Farxiga and Jardiance. Do not apply that extra requirement to Synjardy immediate-release.'])
add('sglt-other','Invokana / Invokamet / Invokamet XR / Segluromet / Steglatro / Trijardy XR',1567,[1570],['Invokana','Invokamet','Invokamet XR','Segluromet','Steglatro','Trijardy XR'],'Type 2 diabetes',['Type 2 diabetes diagnosis.',MET,'Failure, intolerance or contraindication to BOTH brand Farxiga and Jardiance.'],notes=['Age ≥10 applies to Invokana, Invokamet and Invokamet XR ONLY; no separate age threshold is stated here for the other products.','The product heading prints “Inovkana”; the age criterion identifies Invokana. Preserve this source spelling discrepancy for review.'])
add('xigduo','Xigduo XR / generic dapagliflozin-metformin',1567,[1570,1571],['Xigduo XR','generic dapagliflozin-metformin'],'Type 2 diabetes OR CKD OR qualifying HFrEF',[],branches=[dict(label='ONE indication pathway',options=['Type 2 diabetes: age ≥10 years AND '+MET,'CKD; OR heart failure NYHA II–IV with reduced EF.'])],notes=['Generic dapagliflozin-metformin ALSO requires failure, intolerance or contraindication to brand Xigduo XR.','HFpEF is not listed for this combination in the cited section; do not import Farxiga’s HFpEF branch.'])
add('sglt-combination','Brand bexagliflozin / Brenzavvy / Glyxambi / Qtern / brand dapagliflozin-saxagliptin / Steglujan',1567,[1571,1572],['Brand bexagliflozin','Brenzavvy','Glyxambi','Qtern','Brand dapagliflozin-saxagliptin','Steglujan'],'Type 2 diabetes',['Type 2 diabetes diagnosis.',MET,'Failure, intolerance or contraindication to ALL of these groups/products: Janumet OR Janumet XR; Januvia; Jentadueto; Onglyza; Tradjenta; Trijardy XR.','Failure, intolerance or contraindication to BOTH brand Farxiga and Jardiance.'])
add('inpefa','Inpefa',1567,[1572],['Inpefa'],'CV death / HF hospitalization / urgent HF visit risk reduction',['Adult with heart failure; OR adult with type 2 diabetes, CKD and other cardiovascular risk factors.','Requested use is reduction of CV death, HF hospitalization and urgent HF visits.','Failure, intolerance or contraindication to brand Farxiga.'])
add('soliqua','Soliqua',365,[365,366,367],['Soliqua'],'Type 2 diabetes',['Type 2 diabetes diagnosis.','Inadequately controlled on BOTH a GLP-1 receptor agonist and basal insulin.',DPP],renewal=['Document positive clinical response to therapy.',DPP],stage='Initial authorization and reauthorization')
add('xultophy','Xultophy',365,[366,367],['Xultophy'],'Type 2 diabetes',['Type 2 diabetes diagnosis.','Inadequately controlled on BOTH a GLP-1 receptor agonist and basal insulin.','Failure, intolerance or contraindication to Soliqua.',DPP],renewal=['Document positive clinical response to therapy.',DPP],stage='Initial authorization and reauthorization')
add('triple-asthma','Breztri / Trelegy Ellipta — asthma',265,[265,266,267],['Breztri','Trelegy Ellipta'],'Asthma',['Asthma diagnosis.','Breztri: age ≥12 years. Trelegy Ellipta: age ≥18 years.','Failure, contraindication or intolerance to ALL three preferred groups: (1) Wixela Inhub OR generic fluticasone-salmeterol Diskus OR Advair HFA; (2) Dulera; (3) generic budesonide-formoterol.'],renewal=['Document positive clinical response to therapy.'],stage='Initial authorization and reauthorization')
add('triple-copd','Breztri / Trelegy Ellipta — COPD',265,[266,267],['Breztri','Trelegy Ellipta'],'COPD, including chronic bronchitis and/or emphysema',['COPD diagnosis, including chronic bronchitis and/or emphysema.','Failure, contraindication or intolerance to at least a 30-day trial of BOTH used in combination: Stiolto Respimat AND brand Flovent HFA or generic fluticasone propionate.'],renewal=['Document positive clinical response to therapy.'],stage='Initial authorization and reauthorization',notes=['Do not substitute the asthma prerequisite inhalers for the COPD combination trial.'])
add('ics-preferred','Arnuity Ellipta / Asmanex / Qvar Redihaler — policy-preferred products',961,[961,962],['brand Arnuity Ellipta','Asmanex HFA','Asmanex Twisthaler','Qvar Redihaler'],'Asthma',['Asthma diagnosis.'],notes=['This section’s prior-therapy requirements apply to nonpreferred requests, not to these policy-preferred products.','Do not infer that these products always require PA; use the separate formulary restriction fields.'])
add('ics-nonpreferred','Alvesco / generic fluticasone furoate / beclomethasone HFA',961,[961,962],['Alvesco','generic fluticasone furoate','Beclomethasone Dipropionate HFA'],'Asthma',['Asthma diagnosis.','For nonpreferred requests: failure, contraindication or intolerance to a “majority (not more than 3)” of the preferred inhaled corticosteroids listed below.'],notes=['Listed preferred choices: brand Arnuity Ellipta; Asmanex HFA/Twisthaler; brand/generic Flovent Diskus; brand/generic Flovent HFA; Pulmicort Flexhaler; generic budesonide respules; Qvar Redihaler.','Generic fluticasone furoate ALSO requires trial/failure or intolerance to brand Arnuity Ellipta.','Beclomethasone Dipropionate HFA ALSO requires trial/failure or intolerance to Qvar Redihaler.'],ambiguity='The source says “majority (not more than 3)” while listing seven preferred lines. The required trial count needs Banner clarification; no numeric approval rule is inferred.')
add('u500','Humulin R U-500 vial / KwikPen',969,[969,970],['Humulin R U-500 vial','Humulin R U-500 KwikPen'],'Need for concentrated insulin',[],branches=[dict(label='ONE pathway',options=['Failure, intolerance or contraindication to BOTH groups: insulin aspart OR insulin lispro; AND Lantus.','Document a reason or special circumstance requiring a concentrated insulin product.'])],notes=['This section names Humulin R U-500 only; do not apply it to U-100 Humalog, Toujeo or all concentrated insulins.'])

# Exact product/form crosswalks reviewed against source headings. No coverage inference.
BRAND_GUIDES={'TRULICITY':['glp-preferred'],'VICTOZA':['glp-preferred'],'MOUNJARO':['glp-preferred'],'BYETTA':['glp-nonpreferred-injection'],'FARXIGA':['farxiga'],'JARDIANCE':['jardiance'],'SYNJARDY':['synjardy'],'XIGDUO XR':['xigduo'],'TRIJARDY XR':['sglt-other'],'QVAR REDIHALER':['ics-preferred'],'ARNUITY':['ics-preferred'],'ASMANEX HFA':['ics-preferred'],'ASMANEX TWISTHALER':['ics-preferred'],'HUMULIN R U-500 (CONCENTRATED)':['u500'],'HUMULIN R U-500 KWIKPEN':['u500']}
def main():
 p=ROOT/'dist/data.json';data=json.loads(p.read_text());before=copy.deepcopy(data)
 data['policies']=[r for r in data['policies'] if not r.get('guide')]+GUIDES
 linked=[]
 for m in data['medications']:
  if m['planId']!='banner-ufc':continue
  ids=BRAND_GUIDES.get(m['brand'],[])
  if ids:m['approvalGuideIds']=['banner-guide-'+i for i in ids];linked.append(m['id'])
 data['meta']['asOf']='2026-11-10'
 data['categories']=sorted({r['category'] for r in data['medications']+data['policies']})
 data['subcategories']={c:sorted({r['subcategory'] for r in data['medications']+data['policies'] if r['category']==c}) for c in data['categories']}
 plan=next(r for r in data['plans'] if r['id']=='banner-ufc')
 plan['detail']=plan['detail'].replace('Detailed clinical criteria remain source text, without clinician-approved summaries.','Policies without a structured guide retain source-text/index status.')
 plan['detail']=re.sub(r' \d+ source-reviewed diabetes and respiratory PA guides.*$','',plan['detail'])
 plan['detail']+=' '+f'{len(GUIDES)} source-reviewed diabetes and respiratory PA guides are available; ambiguous steroid trial-count wording is flagged. Guides do not change the formulary PA flags.'
 for evidence in data['planEvidence']:
  if evidence['id']=='banner-nov26-pa':evidence['evidence']='All 479 November policy sections indexed with exact source pages. Seventeen source-reviewed diabetes and respiratory guides summarize selected sections, with indication-specific requirements and explicit renewal provenance; remaining sections are indexed source text.'
 audit=dict(date='2026-11-10',guide_count=len(GUIDES),linked_medications=len(linked),medication_ids=linked,source_sha256=hashlib.sha256((ROOT/'dist'/PDF.lstrip('/')).read_bytes()).hexdigest(),guides=GUIDES,internal_review='All 27 June internal PDF pages checked for matching product/indication rules; no applicable overriding rule found for these guide targets. Eohilia oral suspension and DPP-4/metformin lifetime approvals do not establish rules for these separate products.',not_clinician_approved=True)
 for a,b in zip(before['medications'],data['medications']):assert {k:v for k,v in a.items() if k!='approvalGuideIds'}=={k:v for k,v in b.items() if k!='approvalGuideIds'}
 assert len(before['medications'])==len(data['medications'])==5563
 dbpath=ROOT/'data/medication_coverage_v0.26.sqlite'
 if not dbpath.exists():shutil.copyfile(ROOT/'data/medication_coverage_v0.25.sqlite',dbpath)
 db=sqlite3.connect(dbpath)
 db.execute('CREATE TABLE IF NOT EXISTS banner_approval_guides(id TEXT PRIMARY KEY,source_effective TEXT,source_first_page INTEGER,source_last_page INTEGER,status TEXT,guide_json TEXT)')
 db.execute('CREATE TABLE IF NOT EXISTS banner_approval_guide_links(record_id TEXT,guide_id TEXT REFERENCES banner_approval_guides(id),PRIMARY KEY(record_id,guide_id))')
 for g in GUIDES:db.execute('INSERT OR REPLACE INTO banner_approval_guides VALUES(?,?,?,?,?,?)',(g['id'],g['sourceEffective'],g['sourcePage'],g['sourceLastPage'],g['validation'],json.dumps(g)))
 for m in data['medications']:
  for gid in m.get('approvalGuideIds',[]):db.execute('INSERT OR IGNORE INTO banner_approval_guide_links VALUES(?,?)',(m['id'],gid))
 db.commit();assert db.execute('PRAGMA integrity_check').fetchone()[0]=='ok';assert not db.execute('PRAGMA foreign_key_check').fetchall();db.close()
 p.write_text(json.dumps(data,ensure_ascii=False,separators=(',',':')))
 (ROOT/'audits/banner_approval_guides_2026-11-10.json').write_text(json.dumps(audit,ensure_ascii=False,indent=2))
 print({'guides':len(GUIDES),'linked_medications':len(linked),'medication_flags_unchanged':True})
if __name__=='__main__':main()
